using System.Globalization;
using System.IO;
using System.Text;
using Microsoft.EntityFrameworkCore;
using Produktionsplanung.App.Data;
namespace Produktionsplanung.App.Services;
public static class CsvExportService{
 private static readonly CultureInfo C=CultureInfo.GetCultureInfo("de-CH");public static string ExportAll(string baseDirectory,AppSettings settings){var dir=Path.Combine(baseDirectory,$"OpsCompact-Export-{DateTime.Now:yyyyMMdd-HHmmss}");Directory.CreateDirectory(dir);var d=string.IsNullOrEmpty(settings.CsvDelimiter)?';':settings.CsvDelimiter[0];var enc=new UTF8Encoding(settings.IncludeUtf8Bom);using var db=new AppDbContext();ExportEmployees(db,dir,d,enc);ExportWorkstations(db,dir,d,enc);ExportWorkstationShiftRules(db,dir,d,enc);ExportSkills(db,dir,d,enc);ExportShifts(db,dir,d,enc);ExportAbsences(db,dir,d,enc);ExportWorkTime(db,dir,d,enc);ExportOperatingCalendar(db,dir,d,enc);ExportPlanning(db,dir,d,enc);ExportOrders(db,dir,d,enc);ExportRunSlots(db,dir,d,enc);ExportActuals(db,dir,d,enc);ExportDowntimes(db,dir,d,enc);return dir;}
 private static void Write(string dir,string file,List<string> lines,Encoding enc)=>File.WriteAllLines(Path.Combine(dir,file),lines,enc);private static void ExportEmployees(AppDbContext db,string dir,char d,Encoding e){var l=new List<string>{Join(d,"Personalnummer","Nachname","Vorname","Funktion","Abteilung","Pensum %","Sollstunden/Woche","Aktiv")};foreach(var x in db.Employees.AsNoTracking().OrderBy(x=>x.LastName).ThenBy(x=>x.FirstName))l.Add(Join(d,x.PersonnelNumber,x.LastName,x.FirstName,x.Role,x.Department,x.WorkloadPercent.ToString(C),x.WeeklyTargetHours.ToString("0.##",C),x.IsActive?"Ja":"Nein"));Write(dir,"mitarbeiter.csv",l,e);}private static void ExportWorkstations(AppDbContext db,string dir,char d,Encoding e){var l=new List<string>{Join(d,"Arbeitsplatz","Bereich","Minimum","Optimal","Maximum","Pflichtqualifikation","Mindest-Level","Aktiv")};foreach(var x in db.Workstations.AsNoTracking().Include(x=>x.RequiredQualification).OrderBy(x=>x.Name))l.Add(Join(d,x.Name,x.Area,x.MinimumStaff.ToString(C),x.OptimalStaff.ToString(C),x.MaximumStaff.ToString(C),x.RequiredQualification?.Name??"",x.RequiredQualificationLevel>0?x.RequiredQualificationLevel.ToString(C):"",x.IsActive?"Ja":"Nein"));Write(dir,"arbeitsplaetze.csv",l,e);}
 private static void ExportWorkstationShiftRules(AppDbContext db,string dir,char d,Encoding e){var l=new List<string>{Join(d,"Arbeitsplatz","Schicht","Montag","Dienstag","Mittwoch","Donnerstag","Freitag","Samstag","Sonntag")};foreach(var x in db.WorkstationShiftRules.AsNoTracking().Include(x=>x.Workstation).Include(x=>x.Shift).AsEnumerable().OrderBy(x=>x.Workstation.Name).ThenBy(x=>x.Shift.StartTime))l.Add(Join(d,x.Workstation.Name,x.Shift.Name,Y(x.Monday),Y(x.Tuesday),Y(x.Wednesday),Y(x.Thursday),Y(x.Friday),Y(x.Saturday),Y(x.Sunday)));Write(dir,"arbeitsplatz_schichtregeln.csv",l,e);}private static void ExportSkills(AppDbContext db,string dir,char d,Encoding e){var l=new List<string>{Join(d,"Personalnummer","Mitarbeiter","Qualifikation","Level")};foreach(var x in db.EmployeeQualifications.AsNoTracking().Include(x=>x.Employee).Include(x=>x.Qualification).OrderBy(x=>x.Employee.LastName).ThenBy(x=>x.Qualification.Name))l.Add(Join(d,x.Employee.PersonnelNumber,$"{x.Employee.LastName}, {x.Employee.FirstName}",x.Qualification.Name,x.Level.ToString(C)));Write(dir,"skill_matrix.csv",l,e);}private static void ExportShifts(AppDbContext db,string dir,char d,Encoding e){var l=new List<string>{Join(d,"Schicht","Start","Ende","Pause min")};foreach(var x in db.Shifts.AsNoTracking().AsEnumerable().OrderBy(x=>x.StartTime))l.Add(Join(d,x.Name,x.StartTime.ToString(@"hh\:mm"),x.EndTime.ToString(@"hh\:mm"),x.BreakMinutes.ToString(C)));Write(dir,"schichten.csv",l,e);}
 private static void ExportAbsences(AppDbContext db,string dir,char d,Encoding e){var l=new List<string>{Join(d,"Personalnummer","Mitarbeiter","Typ","Von","Bis","Kommentar")};foreach(var x in db.Absences.AsNoTracking().Include(x=>x.Employee).OrderBy(x=>x.StartDate))l.Add(Join(d,x.Employee.PersonnelNumber,$"{x.Employee.LastName}, {x.Employee.FirstName}",x.Type,x.StartDate.ToString("dd.MM.yyyy"),x.EndDate.ToString("dd.MM.yyyy"),x.Comment??""));Write(dir,"abwesenheiten.csv",l,e);}private static void ExportWorkTime(AppDbContext db,string dir,char d,Encoding e){var l=new List<string>{Join(d,"Datum","Personalnummer","Mitarbeiter","Start","Ende","Pause min","Netto h","Kommentar")};foreach(var x in db.WorkTimeEntries.AsNoTracking().Include(x=>x.Employee).AsEnumerable().OrderBy(x=>x.Date).ThenBy(x=>x.StartTime))l.Add(Join(d,x.Date.ToString("dd.MM.yyyy"),x.Employee.PersonnelNumber,$"{x.Employee.LastName}, {x.Employee.FirstName}",x.StartTime.ToString(@"hh\:mm"),x.EndTime.ToString(@"hh\:mm"),x.BreakMinutes.ToString(C),OperatingCalendarService.CalculateNetHours(x.StartTime,x.EndTime,x.BreakMinutes).ToString("0.##",C),x.Comment??""));Write(dir,"arbeitszeiten.csv",l,e);}private static void ExportOperatingCalendar(AppDbContext db,string dir,char d,Encoding e){var l=new List<string>{Join(d,"Datum","Bezeichnung","Arbeitstag","Sollstunden-Faktor","Kommentar")};foreach(var x in db.OperatingCalendarDays.AsNoTracking().OrderBy(x=>x.Date))l.Add(Join(d,x.Date.ToString("dd.MM.yyyy"),x.Name,Y(x.IsWorkingDay),x.TargetHoursFactor.ToString("0.##",C),x.Comment??""));Write(dir,"betriebskalender.csv",l,e);}
 private static void ExportPlanning(AppDbContext db,string dir,char d,Encoding e){var l=new List<string>{Join(d,"Datum","Personalnummer","Mitarbeiter","Arbeitsplatz","Schicht","Start","Ende","Pause min","Kommentar")};foreach(var x in db.PlanningAssignments.AsNoTracking().Include(x=>x.Employee).Include(x=>x.Workstation).Include(x=>x.Shift).AsEnumerable().OrderBy(x=>x.Date).ThenBy(x=>x.StartTime))l.Add(Join(d,x.Date.ToString("dd.MM.yyyy"),x.Employee.PersonnelNumber,$"{x.Employee.LastName}, {x.Employee.FirstName}",x.Workstation.Name,x.Shift?.Name??"Individuell",x.StartTime.ToString(@"hh\:mm"),x.EndTime.ToString(@"hh\:mm"),x.BreakMinutes.ToString(C),x.Comment??""));Write(dir,"planung.csv",l,e);}
 private static void ExportOrders(AppDbContext db,string dir,char d,Encoding e){var l=new List<string>{Join(d,"Auftrag","Produkt","Menge","Einheit","Priorität","Plan-Datum","Arbeitsplatz","Startschicht","Geplante Schichten","Personalbedarf","Status","Kommentar")};foreach(var x in db.ProductionOrders.AsNoTracking().Include(x=>x.Workstation).Include(x=>x.Shift).OrderBy(x=>x.PlannedDate).ThenBy(x=>x.OrderNumber))l.Add(Join(d,x.OrderNumber,x.Product,x.Quantity.ToString("0.##",C),x.Unit,x.Priority,x.PlannedDate.ToString("dd.MM.yyyy"),x.Workstation.Name,x.Shift?.Name??"Individuell",x.PlannedShiftCount.ToString(C),x.RequiredStaff.ToString(C),x.Status,x.Comment??""));Write(dir,"produktionsauftraege.csv",l,e);}private static void ExportRunSlots(AppDbContext db,string dir,char d,Encoding e){var l=new List<string>{Join(d,"Auftrag","Lauf-Nr","Datum","Schicht","Start","Ende","Pause min")};foreach(var x in db.ProductionRunSlots.AsNoTracking().Include(x=>x.ProductionOrder).Include(x=>x.Shift).AsEnumerable().OrderBy(x=>x.Date).ThenBy(x=>x.SequenceNumber))l.Add(Join(d,x.ProductionOrder.OrderNumber,x.SequenceNumber.ToString(C),x.Date.ToString("dd.MM.yyyy"),x.Shift.Name,x.Shift.StartTime.ToString(@"hh\:mm"),x.Shift.EndTime.ToString(@"hh\:mm"),x.Shift.BreakMinutes.ToString(C)));Write(dir,"produktionslaeufe.csv",l,e);}
 private static void ExportActuals(AppDbContext db,string dir,char d,Encoding e){var l=new List<string>{Join(d,"Datum","Auftrag","Produkt","Einheit","Arbeitsplatz","Schicht","Lauf-Nr","Gesamtmenge","Gutmenge","Ausschuss","Planzeit min","Laufzeit min","Stillstand min","Sollrate/h","Verfügbarkeit %","Leistung %","Qualität %","OEE %","Kommentar")};var rows=db.ProductionActuals.AsNoTracking().Include(x=>x.ProductionOrder).ThenInclude(x=>x.Workstation).Include(x=>x.ProductionRunSlot).ThenInclude(x=>x!.Shift).Include(x=>x.Downtimes).OrderBy(x=>x.Date).ToList();foreach(var x in rows){var m=OeeAnalyticsService.Calculate(x.PlannedProductionMinutes,x.RunMinutes,x.TotalQuantity,x.GoodQuantity,x.IdealRatePerHour);l.Add(Join(d,x.Date.ToString("dd.MM.yyyy"),x.ProductionOrder.OrderNumber,x.ProductSnapshot??x.ProductionOrder.Product,x.UnitSnapshot??x.ProductionOrder.Unit,x.WorkstationNameSnapshot??x.ProductionOrder.Workstation.Name,x.ShiftNameSnapshot??x.ProductionRunSlot?.Shift.Name??"Legacy / nicht eindeutig",x.ProductionRunSlot?.SequenceNumber.ToString(C)??"",x.TotalQuantity.ToString("0.##",C),x.GoodQuantity.ToString("0.##",C),x.ScrapQuantity.ToString("0.##",C),x.PlannedProductionMinutes.ToString("0.##",C),x.RunMinutes.ToString("0.##",C),x.Downtimes.Sum(z=>z.Minutes).ToString("0.##",C),x.IdealRatePerHour.ToString("0.##",C),m.AvailabilityPercent.ToString("0.0",C),m.PerformancePercent.ToString("0.0",C),m.QualityPercent.ToString("0.0",C),m.OeePercent.ToString("0.0",C),x.Comment??""));}Write(dir,"ist_produktion_oee.csv",l,e);}private static void ExportDowntimes(AppDbContext db,string dir,char d,Encoding e){var l=new List<string>{Join(d,"Datum","Auftrag","Arbeitsplatz","Grund","Minuten","Kommentar")};foreach(var x in db.DowntimeEntries.AsNoTracking().Include(x=>x.ProductionActual).ThenInclude(x=>x.ProductionOrder).ThenInclude(x=>x.Workstation).OrderBy(x=>x.ProductionActual.Date))l.Add(Join(d,x.ProductionActual.Date.ToString("dd.MM.yyyy"),x.ProductionActual.ProductionOrder.OrderNumber,x.ProductionActual.WorkstationNameSnapshot??x.ProductionActual.ProductionOrder.Workstation.Name,x.Reason,x.Minutes.ToString("0.##",C),x.Comment??""));Write(dir,"stillstaende.csv",l,e);}
 private static string Y(bool v)=>v?"Ja":"Nein";private static string Join(char d,params string[] values)=>string.Join(d,values.Select(v=>Escape(v,d)));private static string Escape(string value,char d){value??="";if(value.Contains('"')||value.Contains(d)||value.Contains('\n')||value.Contains('\r'))return $"\"{value.Replace("\"","\"\"")}\"";return value;}
}
